const input = $input.first().json;
const webhookBody = input.body || input;
const payload = webhookBody.payload || webhookBody;

// 1. Ignore non-message WAHA events (e.g. session.status, message.ack)
const event = webhookBody.event || '';
if (event && event !== 'message' && event !== 'message.any') {
  return [];
}

// 2. Ignore outgoing messages from ourselves
if (payload.fromMe === true || payload._data?.key?.fromMe === true) {
  return [];
}

// 3. Extract the exact WAHA session that received this message (e.g. company_5, default)
const sessionName = (webhookBody.session || payload.session || '').toString().trim();

// 4. Ignore group messages, status broadcasts, and newsletters/channels
const rawFrom = (payload.from || payload._data?.key?.remoteJid || '').toString();
if (
  rawFrom.includes('@g.us') ||
  rawFrom.includes('@broadcast') ||
  rawFrom.includes('@newsletter')
) {
  return [];
}

// 5. Extract message text
let rawText = '';
if (typeof payload.body === 'string') {
  rawText = payload.body;
} else if (payload.message && typeof payload.message.conversation === 'string') {
  rawText = payload.message.conversation;
} else if (payload._data?.message?.conversation && typeof payload._data.message.conversation === 'string') {
  rawText = payload._data.message.conversation;
} else if (payload._data?.message?.extendedTextMessage?.text) {
  rawText = payload._data.message.extendedTextMessage.text;
} else if (typeof payload.text === 'string') {
  rawText = payload.text;
}

if (!rawText || typeof rawText !== 'string' || !rawText.trim()) {
  return [];
}

// Helper: strip @domain and :device suffix, keep digits only
const cleanJid = (jid) => {
  if (!jid || typeof jid !== 'string') return '';
  return jid.split('@')[0].split(':')[0].replace(/\D/g, '');
};
const isPhoneJid = (jid) => typeof jid === 'string' && (jid.includes('@s.whatsapp.net') || jid.includes('@c.us'));
const isLidJid = (jid) => typeof jid === 'string' && jid.includes('@lid');

// 6. Extract Customer Phone and ChatId (preserving @lid when no phone JID exists)
const remoteJid = (payload._data?.key?.remoteJid || payload.from || '').toString();
const remoteJidAlt = (payload._data?.key?.remoteJidAlt || '').toString();
const payloadFrom = (payload.from || '').toString();

let phoneJid = '';
if (isPhoneJid(remoteJidAlt)) {
  phoneJid = remoteJidAlt;
} else if (isPhoneJid(remoteJid)) {
  phoneJid = remoteJid;
} else if (isPhoneJid(payloadFrom)) {
  phoneJid = payloadFrom;
}

let customerPhone = '';
let customerChatId = '';
if (phoneJid) {
  customerPhone = cleanJid(phoneJid);
  customerChatId = customerPhone ? (customerPhone + '@c.us') : phoneJid;
} else if (isLidJid(payloadFrom) || isLidJid(remoteJid)) {
  const lidJid = isLidJid(payloadFrom) ? payloadFrom : remoteJid;
  customerPhone = cleanJid(lidJid);
  customerChatId = customerPhone ? (customerPhone + '@lid') : lidJid;
} else {
  customerPhone = cleanJid(remoteJid || payloadFrom);
  customerChatId = customerPhone ? (customerPhone + '@c.us') : (payloadFrom || remoteJid);
}

// 7. Extract Receiving Company WhatsApp Number dynamically (from WAHA me.id or payload.to)
const rawCompanyJid = webhookBody.me?.id || payload.to || webhookBody.to || '';
const companyWhatsapp = cleanJid(rawCompanyJid);

// 8. Extract Customer Name
let name = (payload.pushName || payload._data?.pushName || '').toString();
name = name.replace(/^~+|~+$/g, '').trim();

return [{
  json: {
    session: sessionName,
    company_whatsapp: companyWhatsapp,
    customer_phone: customerPhone,
    customer_chatId: customerChatId,
    raw_from: rawFrom,
    customer_name: name,
    raw_message: rawText.trim()
  }
}];

